#!/usr/bin/env bash
# Lock screen status line: battery and now playing  (generated by theme.py)
b=/sys/class/power_supply/BAT0; out=""
if [ -r $b/capacity ]; then
  c=$(cat $b/capacity); s=$(cat $b/status)
  [ "$s" = Charging ] && i="󰂄" || i="󰂀"
  out="$i  $c%"
fi
m=$(playerctl metadata --format '{{title}} — {{artist}}' 2>/dev/null | cut -c1-60)
[ -n "$m" ] && [ "$(playerctl status 2>/dev/null)" = Playing ] && out="$out      󰝚  $m"
echo "$out"
